package com.hiretrack.security;
import com.hiretrack.repo.UserRepository; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;}
 protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String e=jwt.email(h.substring(7));users.findByEmail(e).filter(com.hiretrack.model.User::isActive).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(e,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())))));}catch(Exception ignored){}}c.doFilter(r,s);}
}
